function App() {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      console.log(count); // what does this log?
    }, 1000);
    return () => clearInterval(id);
  }, []); // empty deps

  // count is incremented externally
  return <button onClick={() => setCount(c => c+1)}>+</button>;
}
